interface Named { name: string }
class Person { constructor(public name: string, public age: number) {} }
function greet(who: Named): string { return `hi ${who.name}` }

greet(new Person('Ada', 36))       // OK: it has a name
const pet = { name: 'Rex', legs: 4 }
greet(pet)                         // OK: not a fresh literal
greet({ name: 'Bo', legs: 2 })     // error: 'legs' does not exist in type 'Named'

function describe(value: string | number | null | Date): string {
  if (value === null) return 'nothing'                    // equality
  if (typeof value === 'number') return value.toFixed(1)  // typeof
  if (value instanceof Date) return value.toISOString()   // instanceof
  return value.toUpperCase()                              // only string is left
}

