solution:
type User = { name: string; age: number; email: string | null; tags: string[] }
type ParseResult = { ok: true; user: User } | { ok: false; errors: string[] }

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every(item => typeof item === 'string')
}

function parseUser(input: unknown): ParseResult {
  if (!isRecord(input)) return { ok: false, errors: ['expected an object'] }
  const { name, age, email, tags } = input
  const errors: string[] = []

  const cleanName = typeof name === 'string' ? name.trim() : ''
  if (cleanName === '') errors.push('name: expected a non-empty string')

  const cleanAge = typeof age === 'number' && Number.isInteger(age) && age >= 0 ? age : null
  if (cleanAge === null) errors.push('age: expected a non-negative integer')

  let cleanEmail: string | null = null
  if (email != null) {
    if (typeof email === 'string' && email.includes('@')) cleanEmail = email.trim().toLowerCase()
    else errors.push('email: expected a string containing @')
  }

  let cleanTags: string[] = []
  if (tags != null) {
    if (isStringArray(tags)) cleanTags = [...new Set(tags)]
    else errors.push('tags: expected an array of strings')
  }

  if (errors.length > 0 || cleanAge === null) return { ok: false, errors }
  return { ok: true, user: { name: cleanName, age: cleanAge, email: cleanEmail, tags: cleanTags } }
}

Every field starts as `unknown`, so the compiler forces a check before each use: `typeof` for primitives, `Number.isInteger` for the integer rule, a custom guard for the string array. `email != null` covers both missing and `null` in one comparison. The final `cleanAge === null` test is redundant at runtime but lets the compiler see that `cleanAge` is a `number` in the success branch. The returned object is built from cleaned locals, so unknown keys never leak through. Time is O(n) in the number of tags.

